<?php
function insertRow(string $table,array $data):int{$keys=array_keys($data);run('INSERT INTO '.$table.' ('.implode(',',$keys).') VALUES ('.implode(',',array_fill(0,count($keys),'?')).')',array_values($data));return (int)db()->lastInsertId();}
function seedDatabase():void{global $config;
 $stamp=['created_at'=>now(),'updated_at'=>now()];
 foreach([['Học viên Demo','student1','student'],['Học viên thứ hai','student2','student'],['Giảng viên Demo','instructor1','instructor'],['Giảng viên thứ hai','instructor2','instructor'],['Quản trị viên Demo','admin','admin']] as [$name,$email,$role])insertRow('users',['name'=>$name,'email'=>$email.'@studymate.test','password'=>password_hash($config['demo_password'],PASSWORD_BCRYPT,['cost'=>12]),'role'=>$role,'is_active'=>1,'auth_version'=>1]+$stamp);
 $topics=[['HTML và CSS cơ bản','web','Lập trình web',['Cấu trúc trang HTML','Thẻ và ngữ nghĩa','Form nhập liệu','CSS selector','Bố cục Flexbox','Responsive cơ bản']],['JavaScript cơ bản','programming','Lập trình',['Biến và kiểu dữ liệu','Điều kiện và vòng lặp','Hàm JavaScript','Mảng và đối tượng','DOM và sự kiện','Xử lý bất đồng bộ']],['Nhập môn cơ sở dữ liệu','database','Cơ sở dữ liệu',['Bảng và bản ghi','Khóa chính','Khóa ngoại','Truy vấn SELECT','JOIN cơ bản','Ràng buộc dữ liệu']]];
 $explanations=[['HTML mô tả cấu trúc trang. Bộ khung gồm html, head và body. Head chứa metadata, body chứa nội dung hiển thị.','Các thẻ semantic như main, nav và article mô tả vai trò của nội dung. h1 là tiêu đề chính, h2 là tiêu đề phần.','Form gom các input để gửi dữ liệu. Label liên kết với id của input. Kiểm tra trên server vẫn bắt buộc.','Selector xác định phần tử được áp dụng CSS. .card chọn class card; #main chọn id main.','Flexbox sắp xếp các phần tử theo một trục. gap tạo khoảng cách; flex-wrap cho phép xuống hàng.','Responsive giúp bố cục thích ứng màn hình. Media query thay đổi cách bố trí khi chiều rộng giảm.'],['Biến lưu dữ liệu. const dành cho binding không gán lại; let cho phép gán lại. Tên rõ nghĩa giúp dễ đọc.','if chọn nhánh dựa trên điều kiện. for lặp thao tác nhiều lần. Cần kiểm tra điều kiện dừng.','Hàm gom thao tác có thể tái sử dụng. Tham số là đầu vào, return trả kết quả cho nơi gọi.','Mảng chứa danh sách phần tử. Đối tượng gom dữ liệu có tên thuộc tính. map tạo mảng mới từ từng phần tử.','DOM biểu diễn cấu trúc tài liệu. Sự kiện click phát sinh khi người dùng tương tác. addEventListener đăng ký xử lý.','Promise biểu diễn kết quả thao tác bất đồng bộ. await đợi Promise bên trong async function; try/catch xử lý lỗi.'],['Bảng chứa các bản ghi có cùng cấu trúc cột. Thiết kế dữ liệu rõ ràng giúp truy vấn và kiểm tra dễ hơn.','Khóa chính xác định duy nhất mỗi bản ghi và không được null. Tránh dùng tên hiển thị làm khóa chính.','Khóa ngoại liên kết tới khóa của bảng khác. Khi xóa dữ liệu cha, cần lựa chọn restrict hoặc cascade phù hợp.','SELECT truy xuất dữ liệu; WHERE lọc bản ghi; ORDER BY quyết định thứ tự. Dùng prepared statement cho dữ liệu người dùng.','JOIN kết hợp dữ liệu từ nhiều bảng thông qua điều kiện. Chọn đúng quan hệ để tránh nhân bản dòng ngoài ý muốn.','UNIQUE bảo đảm giá trị hoặc tổ hợp không trùng. FK bảo đảm tham chiếu hợp lệ. Transaction giữ nhiều thay đổi nguyên tử.']];
 $snippets=["<main>\n  <h1>StudyMate</h1>\n  <p>Học mỗi ngày.</p>\n</main>","const progress = 3 / 6 * 100;\nconsole.log(progress);","SELECT title FROM courses\nWHERE status = 'published';"];
 $prompts=[['HTML có vai trò chính nào?','CSS dùng để làm gì?','Thẻ h1 thường biểu thị gì?','Flexbox hỗ trợ điều gì?','Responsive giúp website thế nào?'],['Biến dùng để làm gì?','Hàm giúp tổ chức code thế nào?','Mảng lưu loại dữ liệu nào?','DOM biểu diễn điều gì?','Promise mô tả điều gì?'],['Khóa chính có đặc điểm gì?','Khóa ngoại có vai trò nào?','SELECT dùng để làm gì?','JOIN được dùng khi nào?','UNIQUE bảo đảm điều gì?']];
 $right=[['Cấu trúc nội dung trang','Trình bày giao diện','Tiêu đề chính','Bố trí phần tử theo trục','Thích ứng các màn hình'],['Lưu dữ liệu','Gom thao tác tái sử dụng','Danh sách phần tử','Cấu trúc tài liệu','Kết quả bất đồng bộ'],['Duy nhất và không null','Liên kết các bảng','Truy xuất dữ liệu','Kết hợp dữ liệu bảng','Giá trị không trùng']];
 $lessonsByCourse=[];
 foreach($topics as $i=>[$title,$cover,$category,$titles]){
  $cat=insertRow('categories',['name'=>$category]+$stamp);$c=insertRow('courses',['instructor_id'=>3,'category_id'=>$cat,'title'=>$title,'description'=>'Khóa học nhập môn với bài học ngắn gọn, ví dụ thực hành và quiz cuối khóa. Bạn có thể học theo nhịp độ riêng.','cover_key'=>$cover,'status'=>$i===2?'draft':'published']+$stamp);
  for($ch=0;$ch<2;$ch++){$chapter=insertRow('chapters',['course_id'=>$c,'title'=>$ch?'Thực hành và ứng dụng':'Kiến thức nền tảng','position'=>$ch+1]+$stamp);for($k=0;$k<3;$k++){$n=$ch*3+$k;$body='# '.$titles[$n]."\n\n".$explanations[$i][$n]."\n\n## Ví dụ tham khảo\n\n```".['html','javascript','sql'][$i]."\n".$snippets[$i]."\n```\n\n## Thực hành\n\nHãy giải thích kiến thức trong bài bằng lời của bạn và tạo một ví dụ nhỏ. So sánh kết quả với nội dung bài trước khi đánh dấu hoàn thành.";$lessonsByCourse[$c][]=insertRow('lessons',['chapter_id'=>$chapter,'title'=>$titles[$n],'body'=>$body,'youtube_video_id'=>null,'position'=>$k+1]+$stamp);}}
  $quiz=insertRow('quizzes',['course_id'=>$c]+$stamp);for($k=0;$k<5;$k++){$q=insertRow('questions',['quiz_id'=>$quiz,'prompt'=>$prompts[$i][$k],'explanation'=>$right[$i][$k].' là đáp án phù hợp với bài học. Hãy xem lại ví dụ nếu bạn còn nhầm.','position'=>$k+1]+$stamp);$correct=($k+$i)%4;$choices=['Chỉ dùng để gửi email','Tự động loại bỏ mọi lỗi phần mềm','Luôn thay thế cơ sở dữ liệu','Không liên quan đến dữ liệu hoặc giao diện'];$choices[$correct]=$right[$i][$k];foreach($choices as $a=>$text)insertRow('answers',['question_id'=>$q,'text'=>$text,'is_correct'=>(int)($a===$correct),'position'=>$a+1]+$stamp);}
 }
 insertRow('enrollments',['user_id'=>1,'course_id'=>2,'last_lesson_id'=>$lessonsByCourse[2][0],'completed_at'=>null]+$stamp);insertRow('lesson_progress',['user_id'=>1,'lesson_id'=>$lessonsByCourse[2][0],'completed_at'=>now()]+$stamp);
}
